CREATE TABLE zip_batches (id TEXT PRIMARY KEY NOT NULL, owner TEXT NOT NULL, source TEXT NOT NULL, token TEXT NOT NULL, fingerprint TEXT NOT NULL, bucket TEXT NOT NULL, archive_key TEXT NOT NULL, input_identity TEXT NOT NULL, captured_options TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'open', manifest_prepared BOOLEAN NOT NULL DEFAULT FALSE, source_published BOOLEAN NOT NULL DEFAULT FALSE, terminal_result TEXT, root_status TEXT NOT NULL DEFAULT 'pending', root_error_code TEXT, root_cid TEXT, root_revision BIGINT NOT NULL DEFAULT 0, root_epoch BIGINT NOT NULL DEFAULT 0, created_at @TIME@ NOT NULL, updated_at @TIME@ NOT NULL, legacy_input_proof_json TEXT, CONSTRAINT ck_zip_batch_identity CHECK(length(id)>0 AND length(owner)>0 AND length(token)>0 AND length(fingerprint)>0 AND length(bucket)>0 AND length(archive_key)>0 AND length(input_identity)>0 AND length(captured_options)>0), CONSTRAINT ck_zip_batch_source CHECK(source IN ('direct','mpu','import')), CONSTRAINT ck_zip_batch_state CHECK(state IN ('open','published')), CONSTRAINT ck_zip_batch_root_status CHECK(root_status IN ('pending','disabled','empty','failed','complete','partial')), CONSTRAINT ck_zip_batch_revision CHECK(root_revision>=0 AND root_epoch>=0), CONSTRAINT ck_zip_batch_terminal CHECK((state='open' AND terminal_result IS NULL) OR (state='published' AND terminal_result IS NOT NULL)), CONSTRAINT ck_zip_batch_root_shape CHECK((root_status IN ('complete','partial') AND root_cid IS NOT NULL AND length(root_cid)>0 AND root_error_code IS NULL) OR (root_status='failed' AND root_cid IS NULL AND root_error_code IS NOT NULL AND length(root_error_code)>0) OR (root_status IN ('pending','disabled','empty') AND root_cid IS NULL AND root_error_code IS NULL)));
CREATE TABLE zip_manifest_entries (batch_id TEXT NOT NULL REFERENCES zip_batches(id) ON DELETE RESTRICT, path TEXT NOT NULL, object_key TEXT, cid TEXT, size BIGINT, version_row_id TEXT, error_code TEXT, created_at @TIME@ NOT NULL, PRIMARY KEY(batch_id,path), CONSTRAINT ck_zip_manifest_path CHECK(length(path)>0), CONSTRAINT ck_zip_manifest_shape CHECK((object_key IS NOT NULL AND length(object_key)>0 AND cid IS NOT NULL AND length(cid)>0 AND size IS NOT NULL AND size>=0 AND error_code IS NULL) OR (object_key IS NULL AND cid IS NULL AND size IS NULL AND version_row_id IS NULL AND error_code IS NOT NULL AND length(error_code)>0)), CONSTRAINT ck_zip_manifest_version CHECK(version_row_id IS NULL OR length(version_row_id)>0));
CREATE TABLE zip_root_builds (batch_id TEXT NOT NULL REFERENCES zip_batches(id) ON DELETE RESTRICT, revision BIGINT NOT NULL, epoch BIGINT NOT NULL, worker TEXT NOT NULL, lease_until @TIME@ NOT NULL, status TEXT NOT NULL, error_code TEXT, created_at @TIME@ NOT NULL, updated_at @TIME@ NOT NULL, PRIMARY KEY(batch_id,revision,epoch), CONSTRAINT ck_zip_build_fence CHECK(revision>0 AND epoch>0 AND length(worker)>0), CONSTRAINT ck_zip_build_status CHECK(status IN ('intent','reconciling','invoked','unknown','verified','failed')), CONSTRAINT ck_zip_build_failure CHECK((status='failed' AND error_code IS NOT NULL AND length(error_code)>0) OR (status<>'failed' AND error_code IS NULL)));
CREATE TABLE zip_root_references (batch_id TEXT NOT NULL, revision BIGINT NOT NULL, epoch BIGINT NOT NULL, node_identity TEXT NOT NULL, tier TEXT NOT NULL, cid TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'retained', verification_receipt TEXT, created_at @TIME@ NOT NULL, updated_at @TIME@ NOT NULL, logical_released_at @RELEASE_TIME@ DEFAULT NULL, PRIMARY KEY(batch_id,revision,epoch,node_identity,tier,cid), CONSTRAINT fk_zip_root_intent FOREIGN KEY(batch_id,revision,epoch) REFERENCES zip_root_builds(batch_id,revision,epoch) ON DELETE RESTRICT, CONSTRAINT ck_zip_root_identity CHECK(length(node_identity)>0 AND length(cid)>0 AND tier IN ('hot','cold')), CONSTRAINT ck_zip_root_state CHECK(state IN ('retained','adopted')), CONSTRAINT ck_zip_root_receipt CHECK(verification_receipt IS NULL OR length(verification_receipt)>0), CONSTRAINT ck_zip_root_adopted CHECK(state='retained' OR verification_receipt IS NOT NULL));
CREATE UNIQUE INDEX uq_zip_batch_intent ON zip_batches(owner,source,token);
CREATE INDEX idx_zip_batch_recovery ON zip_batches(state,root_status,id);
CREATE UNIQUE INDEX uq_zip_manifest_version ON zip_manifest_entries(version_row_id) WHERE version_row_id IS NOT NULL;
CREATE INDEX idx_zip_build_recovery ON zip_root_builds(status,lease_until,batch_id);
CREATE UNIQUE INDEX uq_zip_root_adopted ON zip_root_references(batch_id) WHERE state='adopted';
CREATE INDEX idx_zip_root_physical ON zip_root_references(tier,node_identity,cid,state);
CREATE TABLE zip_mpu_replays (batch_id TEXT PRIMARY KEY NOT NULL REFERENCES zip_batches(id) ON DELETE RESTRICT, request_fingerprint TEXT NOT NULL, request_contract TEXT NOT NULL, prepared_archive_cid TEXT, archive_cid TEXT, archive_size BIGINT, public_version_id TEXT, server_side_encryption TEXT, response_xml TEXT, response_headers_json TEXT, CONSTRAINT ck_zip_mpu_request CHECK(length(request_fingerprint)=64 AND length(request_contract)>0), CONSTRAINT ck_zip_mpu_prepared_archive CHECK(prepared_archive_cid IS NULL OR length(prepared_archive_cid)>0), CONSTRAINT ck_zip_mpu_result CHECK((archive_cid IS NULL AND archive_size IS NULL AND public_version_id IS NULL AND server_side_encryption IS NULL AND response_xml IS NULL AND response_headers_json IS NULL) OR (archive_cid IS NOT NULL AND prepared_archive_cid IS NOT NULL AND archive_cid=prepared_archive_cid AND length(archive_cid)>0 AND archive_size IS NOT NULL AND archive_size>=0 AND response_xml IS NOT NULL AND length(response_xml)>0 AND response_headers_json IS NOT NULL AND length(response_headers_json)>0 AND (public_version_id IS NULL OR length(public_version_id)>0) AND (server_side_encryption IS NULL OR server_side_encryption='AES256'))));
CREATE TABLE zip_v2_executions (id TEXT PRIMARY KEY NOT NULL, owner TEXT NOT NULL, source TEXT NOT NULL, token TEXT NOT NULL, request_fingerprint TEXT NOT NULL, request_contract TEXT NOT NULL, bucket TEXT NOT NULL, source_key TEXT NOT NULL, captured_options TEXT NOT NULL, input_sha256 TEXT, input_art_cid TEXT, input_art_size BIGINT, state TEXT NOT NULL DEFAULT 'pending', epoch BIGINT NOT NULL DEFAULT 0, worker TEXT, lease_until @TIME@, terminal_result TEXT, created_at @TIME@ NOT NULL, updated_at @TIME@ NOT NULL, CONSTRAINT ck_zip_v2_identity CHECK(length(id)>0 AND length(owner)>0 AND length(token)>0 AND length(bucket)>0 AND length(source_key)>0 AND length(captured_options)>0 AND length(request_fingerprint)=64 AND request_fingerprint @HEX@ AND length(request_contract)>0 AND source IN ('direct','mpu','import')), CONSTRAINT ck_zip_v2_input CHECK((input_sha256 IS NULL AND input_art_cid IS NULL AND input_art_size IS NULL) OR (input_sha256 IS NOT NULL AND length(input_sha256)=64 AND input_sha256 @HEX@ AND input_art_cid IS NOT NULL AND length(input_art_cid)>0 AND input_art_size IS NOT NULL AND input_art_size>=0)), CONSTRAINT ck_zip_v2_state CHECK(state IN ('pending','admitted','completed','fenced') AND (state IN ('pending','fenced') OR input_sha256 IS NOT NULL) AND ((state IN ('pending','admitted') AND terminal_result IS NULL) OR (state IN ('completed','fenced') AND terminal_result IS NOT NULL AND length(terminal_result)>0))), CONSTRAINT ck_zip_v2_lease CHECK(epoch>=0 AND ((epoch=0 AND worker IS NULL AND lease_until IS NULL) OR (epoch>0 AND worker IS NOT NULL AND length(worker)>0 AND lease_until IS NOT NULL))));
CREATE TABLE zip_v2_manifest (batch_id TEXT NOT NULL REFERENCES zip_v2_executions(id) ON DELETE RESTRICT, path TEXT NOT NULL, object_key TEXT, cid TEXT, size BIGINT, error_code TEXT, created_at @TIME@ NOT NULL, PRIMARY KEY(batch_id,path), CONSTRAINT ck_zip_v2_manifest_path CHECK(length(path)>0), CONSTRAINT ck_zip_v2_manifest_shape CHECK((object_key IS NOT NULL AND length(object_key)>0 AND cid IS NOT NULL AND length(cid)>0 AND size IS NOT NULL AND size>=0 AND error_code IS NULL) OR (object_key IS NULL AND cid IS NULL AND size IS NULL AND error_code IS NOT NULL AND length(error_code)>0)));
CREATE UNIQUE INDEX uq_zip_v2_intent ON zip_v2_executions(owner,source,token);
CREATE INDEX idx_zip_v2_recovery ON zip_v2_executions(state,lease_until,id);
CREATE UNIQUE INDEX uq_zip_v2_manifest_output ON zip_v2_manifest(batch_id,object_key);
CREATE TABLE zip_v2_targets (batch_id TEXT NOT NULL REFERENCES zip_v2_executions(id) ON DELETE RESTRICT, object_key TEXT NOT NULL, mutation_id TEXT NOT NULL, expected_generation BIGINT NOT NULL, epoch BIGINT NOT NULL, PRIMARY KEY(batch_id,object_key), CONSTRAINT ck_zip_v2_target_guard CHECK(length(object_key)>0 AND length(mutation_id)>0 AND expected_generation>=0 AND epoch>0), CONSTRAINT fk_zip_v2_target_manifest FOREIGN KEY(batch_id,object_key) REFERENCES zip_v2_manifest(batch_id,object_key) ON DELETE RESTRICT);
CREATE TABLE zip_v2_import_requests (batch_id TEXT PRIMARY KEY NOT NULL REFERENCES zip_v2_executions(id) ON DELETE RESTRICT, owner TEXT NOT NULL, bucket TEXT NOT NULL, source_key TEXT NOT NULL, client_token TEXT NOT NULL, prefix TEXT NOT NULL, source_descriptor TEXT NOT NULL, expected_sha256 TEXT, request_contract TEXT NOT NULL, job_state TEXT NOT NULL DEFAULT 'pending', receipt_metadata TEXT, CHECK(length(owner)>0 AND length(bucket)>0 AND length(source_key)>0 AND length(client_token)>0 AND length(prefix)>0 AND length(source_descriptor)>0 AND length(request_contract)>0), CHECK(expected_sha256 IS NULL OR (length(expected_sha256)=64 AND expected_sha256 @HEX@)), CHECK(job_state IN ('pending','failed','ready')), CHECK((job_state='pending' AND receipt_metadata IS NULL) OR job_state<>'pending'));
CREATE UNIQUE INDEX uq_zip_v2_import_token ON zip_v2_import_requests(owner,client_token);
CREATE INDEX idx_zip_v2_import_pending ON zip_v2_import_requests(job_state,batch_id);
CREATE TABLE zip_v2_mpu_intakes (original_upload_id TEXT PRIMARY KEY NOT NULL, active_upload_id TEXT UNIQUE REFERENCES multipart_uploads(upload_id) ON DELETE SET NULL, execution_id TEXT NOT NULL UNIQUE REFERENCES zip_v2_executions(id) ON DELETE RESTRICT, owner TEXT NOT NULL, token TEXT NOT NULL, bucket TEXT NOT NULL, archive_key TEXT NOT NULL, target_prefix TEXT NOT NULL, request_fingerprint TEXT NOT NULL, captured_options TEXT NOT NULL, captured_config TEXT NOT NULL, rule_revision TEXT NOT NULL, created_at @TIME@ NOT NULL, CONSTRAINT ck_zip_v2_mpu_identity CHECK(length(original_upload_id)>0 AND length(execution_id)>0 AND length(owner)>0 AND length(token)>0 AND length(bucket)>0 AND length(archive_key)>0 AND length(target_prefix)>0 AND length(request_fingerprint)=64 AND length(captured_options)>0 AND length(captured_config)>0 AND length(rule_revision)>0), CONSTRAINT ck_zip_v2_mpu_active CHECK(active_upload_id IS NULL OR active_upload_id=original_upload_id), CONSTRAINT uq_zip_v2_mpu_owner_token UNIQUE(owner,token));
CREATE TABLE zip_v2_mpu_completions (upload_id TEXT PRIMARY KEY NOT NULL REFERENCES zip_v2_mpu_intakes(original_upload_id) ON DELETE RESTRICT, owner TEXT NOT NULL, token TEXT NOT NULL, execution_id TEXT NOT NULL, bucket TEXT NOT NULL, archive_key TEXT NOT NULL, part_contract TEXT NOT NULL, response_xml TEXT, response_headers TEXT, CONSTRAINT ck_zip_v2_mpu_receipt CHECK(length(owner)>0 AND length(token)>0 AND length(part_contract)>0 AND ((response_xml IS NULL AND response_headers IS NULL) OR (length(response_xml)>0 AND length(response_headers)>0))));
